def is_safe_name(name: str) -> bool:
    """True when name is a non-empty relative path that stays inside its directory.

    Rejects the empty name, absolute paths, any ".." component, backslashes,
    and NUL characters.
    """
    ex is_safe_name("a.txt") == True
    ex is_safe_name("sub/a.txt") == True
    ex is_safe_name("") == False
    ex is_safe_name("../secret.txt") == False
    ex is_safe_name("a/../../b") == False
    ex is_safe_name("/etc/passwd") == False
    ex is_safe_name("..\\x") == False
    if name.char_count() == 0:
        return False
    if name.startswith("/"):
        return False
    for c in name.chars():
        if c == "\\" or c == "\0":
            return False
    for part in name.split("/"):
        if part == "..":
            return False
    return True

def first_readable(names: list[str]) -> str uses fs:
    """Text of the first name in names that can be read from the directory notes, or "" when none can.

    Reads happen only inside `with fs = fs.sub("notes"):`. A name that fails
    is_safe_name is never read, and a missing or unreadable file is skipped.
    """
    with fs = fs.sub("notes"):
        for name in names:
            if not is_safe_name(name):
                continue
            text = read_or_none(name)
            if text is not None:
                return text
    return ""

def read_or_none(name: str) -> str | None uses fs:
    """Text of the file name in the current fs, or None when it cannot be read."""
    text = fs.read_text(name) else return None
    return text
